var vectors = [
{},
{ a: 1},
{ a: 1, b: [1, 2, 3], c: { d: true, e: null}},
[1, "two", 3.5, false, null],
"a bare string",
42,
true,
null,
{ name: "café", emoji: "🌲🔧", cyrillic: "Привет", cjk: "日本語"}, // multibyte
{ nested: { deep: { deeper: { x: [ { y: 1}]}}}},
