var api = factory();
if (typeof module === "object" && module.exports) module.exports = api;
if (typeof window!== "undefined") {
window.LoopGifts = window.LoopGifts || {};
window.LoopGifts.verifySkin = api.verifySkin;
}
root.__loop21VerifySkin = api;
