else if (type === "zTXt") { entries.push(decodeZTXt(data, inflate));}
else if (type === "iTXt") { entries.push(decodeITXt(data, inflate));}
else if (type === "IEND") { sawIEND = true; off = crcEnd; break;}

off = crcEnd;
