var out = parsePngText(png([IHDR, tEXt("Title", "A Quiet Loop")]));
assert.strictEqual(out.length, 1);
assert.deepStrictEqual(out[0], { kind: "tEXt", keyword: "Title", text: "A Quiet Loop", compressed: false});
